 return `<article class="record arcade-record ${gameId}-record"><header><span>${meta.title}</span><b>本机真实记录</b></header><div class="record-main"><span class="rank-medal">${meta.mark}<br><small>${meta.no}</small></span><div><small>${adventureIds.includes(gameId)?'主线最佳纪录':'炼狱最佳得分'}</small><strong>${scoreText(best)}</strong><p>${best?`${runTime(best)} · ${best.outcome==='clear'?'已通关':'挑战中断'} · 规则 ${best.rulesetVersion.split('@')[1]}`:'完成一局后自动建立档案'}</p></div></div><dl><div><dt>真实局数</dt><dd>${stats.attempts}</dd></div><div><dt>最长运行</dt><dd>${fmt(secondsFromMs(stats.longestDurationMs))}</dd></div><div><dt>${meta.metric}</dt><dd>${Number(total).toLocaleString('zh-CN')}</dd></div></dl></article>`;
