function initArcade(){stopLoop();state.arcadeTime=180;state.arcadeScore=0;state.arcadeTick=0;state.arcadeFuel=100;state.arcadeGoal=0;state.arcadePlayer={x:5,y:13};state.arcadeObjects=[];if(state.arcadeGame==='miner'){state.arcadePlayer={x:1,y:1};state.arcadeObjects=Array.from({length:140},(_,i)=>{const x=i%10,y=Math.floor(i/10);return {x,y,type:(x===0||x===9||y===0||y===13)?'rock':((x*7+y*11)%17===0?'ore':((x*3+y*5)%4===0?'rock':'empty'))}});['1,1','1,2','2,1','2,2','3,2'].forEach(k=>{const [x,y]=k.split(',').map(Number),o=state.arcadeObjects.find(v=>v.x===x&&v.y===y);if(o)o.type='empty'});const exit=state.arcadeObjects.find(v=>v.x===8&&v.y===12);exit.type='exit'}state.playing=false}
