moveArcade=dir=>{if(state.arcadeGame==='racer'&&state.playing){state.arcadeHeat=Math.min(100,state.arcadeHeat+7);state.arcadeCombo++}if(state.arcadeGame==='crossing'&&state.playing&&dir==='up'){state.arcadeCombo=Math.min(9,state.arcadeCombo+1);if(state.arcadeMode==='endless'&&state.arcadePlayer.y===1){state.arcadeScore++;state.arcadePlayer={x:5,y:13};drawArcade();return}}arcadeMoveBase(dir)};
const arcadeStepBase=arcadeStep;
arcadeStep=()=>{if(!state.playing)return;const elapsed=state.arcadeMode==='endless'?state.arcadeTime:180-state.arcadeTime;state.arcadePhase=Math.min(3,1+Math.floor(elapsed/60));if(state.arcadeGame==='racer'){state.arcadeHeat=Math.max(0,state.arcadeHeat-(state.arcadePhase===3?0.4:1.1));const edge=Math.min(3,state.arcadePhase-1);if(state.arcadeTick%(4-state.arcadePhase)===0){const span=Math.max(1,10-edge*2),x=edge+((state.arcadeTick*5+state.arcadePhase*3)%span);state.arcadeObjects.push({x,y:Math.max(0,6-state.arcadePhase*2),type:state.arcadePhase===3?'truck':'car'})}if(state.arcadeHeat>=100){finishArcade(false);return}}else if(state.arcadeGame==='miner'){state.arcadeFuel-=state.arcadePhase;const crushX=Math.min(7,Math.floor(elapsed/18));state.arcadeObjects.filter(o=>o.x<=crushX&&o.y>0&&o.y<13&&o.type==='empty'&&(o.x+o.y+elapsed)%5===0).forEach(o=>o.type='collapse')}else{if(state.arcadeTick%(5-state.arcadePhase)===0){const y=2+((state.arcadeTick*2)%10);state.arcadeObjects.push({x:(state.arcadeTick*7+y)%10,y,type:state.arcadePhase===3?'truck':'car',speed:y%4===0?-1:1})}state.arcadeCombo=Math.max(1,state.arcadeCombo-.03)}arcadeStepBase();updateArcadeHUD()};
const arcadeDrawBase=drawArcade;
drawArcade=()=>{arcadeDrawBase();updateArcadeHUD()};
const arcadePressureStep=arcadeStep;
arcadeStep=()=>{if(state.playing&&state.arcadeMode==='shadow'&&state.arcadeTick%4===0){if(state.arcadeGame==='racer')state.arcadeObjects.push({x:(state.arcadeTick*3)%8+1,y:3,type:'ghost'});if(state.arcadeGame==='crossing')state.arcadeObjects.push({x:(state.arcadeTick*7)%10,y:6,type:'ghost',speed:-1});if(state.arcadeGame==='miner')state.arcadeFuel-=2}arcadePressureStep()};
function updateArcadeHUD(){const elapsed=state.arcadeMode==='endless'?state.arcadeTime:180-state.arcadeTime,phase=document.querySelector('#arcade-phase'),progress=document.querySelector('#phase-progress'),meter=document.querySelector('#arcade-meter'),alert=document.querySelector('#stage-alert'),pressure=document.querySelector('#arcade-pressure');if(phase)phase.textContent=`阶段 ${state.arcadePhase} / 3`;if(progress)progress.style.width=`${Math.min(100,(elapsed%60)/60*100)}%`;document.querySelectorAll('.phase-strip .pressure-lamps i').forEach((lamp,index)=>lamp.classList.toggle('active',index<state.arcadePhase));const page=document.querySelector('.arcade-game');if(page&&page.dataset.phase!==String(state.arcadePhase)){page.classList.remove('phase-1','phase-2','phase-3');page.classList.add(`phase-${state.arcadePhase}`);page.dataset.phase=String(state.arcadePhase)}const value=state.arcadeGame==='racer'?state.arcadeHeat:state.arcadeGame==='miner'?100-state.arcadeFuel:Math.min(100,state.arcadeCombo*11);if(meter)meter.style.width=`${Math.max(4,value)}%`;if(pressure)pressure.textContent=state.arcadeGame==='racer'?`${Math.round(state.arcadeHeat)}%`:state.arcadeGame==='miner'?`${Math.max(0,state.arcadeFuel)}%`:`× ${state.arcadeCombo.toFixed(1)}`;if(alert){alert.textContent=state.arcadePhase===3?'末段狂暴':state.arcadePhase===2?'第二压力已叠加':'第一阶段';alert.classList.toggle('hot',state.arcadePhase===3)}const trafficWave=document.querySelector('#traffic-wave'),trafficWindow=document.querySelector('#traffic-window');if(trafficWave)trafficWave.textContent=state.arcadePhase===3?'高密度':state.arcadePhase===2?'加速中':'建压中';if(trafficWindow)trafficWindow.textContent=state.arcadePhase===3?'极短':'动态计算'}
const arcadeHUDBase=updateArcadeHUD;
updateArcadeHUD=()=>{arcadeHUDBase();if(state.arcadeGame!=='racer')return;const speed=Math.min(328,154+state.arcadePhase*34+Math.floor(state.arcadeScore/18)-Math.floor(state.arcadeHeat/9)),gear=Math.min(6,2+Math.floor(speed/62)),rpm=(5.1+state.arcadePhase*.8+state.arcadeHeat/42).toFixed(1);document.querySelector('#racer-speed')&&(document.querySelector('#racer-speed').textContent=speed);document.querySelector('#racer-gear')&&(document.querySelector('#racer-gear').textContent=gear);document.querySelector('#racer-rpm')&&(document.querySelector('#racer-rpm').textContent=rpm);const bar=document.querySelector('#speed-bar');if(bar)bar.style.width=`${speed/3.28}%`;document.querySelector('.racer-stage')?.style.setProperty('--road-speed',`${Math.max(.16,.42-state.arcadePhase*.07)}s`)};
startArcadeLoop=()=>{state.playing=true;const speeds={racer:[165,130,95],miner:[900,720,560],crossing:[230,185,140]};let scheduledPhase=state.arcadePhase;state.drop=setInterval(arcadeStep,speeds[state.arcadeGame][scheduledPhase-1]);state.timer=setInterval(()=>{state.arcadeTime+=state.arcadeMode==='endless'?1:-1;const elapsed=state.arcadeMode==='endless'?state.arcadeTime:180-state.arcadeTime,newPhase=Math.min(3,1+Math.floor(elapsed/60));state.arcadePhase=newPhase;if(newPhase!==scheduledPhase){scheduledPhase=newPhase;clearInterval(state.drop);state.drop=setInterval(arcadeStep,speeds[state.arcadeGame][newPhase-1]);document.querySelector('.arcade-stage')?.animate([{transform:'translateX(-5px)'},{transform:'translateX(5px)'},{transform:'translateX(0)'}],{duration:220})}document.querySelector('#arcade-clock')&&(document.querySelector('#arcade-clock').textContent=fmt(state.arcadeTime));updateArcadeHUD();if(state.arcadeMode!=='endless'&&state.arcadeTime<=0)finishArcade(state.arcadeGame==='racer'||(state.arcadeGame==='miner'?state.arcadeScore>=8:state.arcadeScore>=12))},1000)};
const arcadeFinishBase=finishArcade;
finishArcade=won=>{if(state.arcadeMode!=='endless'){arcadeFinishBase(won);return}if(!state.playing)return;const metricKey=state.arcadeGame==='racer'?'overtakes':state.arcadeGame==='crossing'?'crossings':'ores',metrics={[metricKey]:state.arcadeScore};if(state.arcadeGame==='crossing')metrics.progressRows=Math.max(0,13-state.arcadePlayer.y);const run=persistRun(state.arcadeGame,'endless',state.arcadeTime,false,metrics,'run_ended');stopLoop();state.rankGame=state.arcadeGame;state.rankMode='endless';showRunResult({won:false,title:'无尽运行已结束',value:`${formatScore(run.score)} PTS`,copy:`${arcadeMeta[state.arcadeGame].stat} ${state.arcadeScore} · 运行 ${fmt(state.arcadeTime)}；${recordNotice(run)}。`,destination:'rank'})};
function finishWave(result){const run=persistRun(result.id,state.waveMode,result.time,result.win,{eventScore:result.score},result.win?'timeout_clear':'collision');state.rankGame=result.id;state.rankMode=state.waveMode;showRunResult({won:result.win,title:result.win?'复合狂暴已突破':'挑战运行已中断',value:`${formatScore(run.score)} PTS`,copy:`${waveMeta[result.id].ui.score} ${result.score} · 运行 ${fmt(result.time)}，成绩来自真实局内事件；${recordNotice(run)}。`,destination:'rank'})}
function finishExpansionGame(result){
 if(!result||!newGameIds.includes(result.id))return;
 const run=persistRun(result.id,state.newGameMode,result.time,result.win,result.metrics,result.endedReason||(result.win?'timeout_clear':'challenge_failed'));
 const profile=PROFILE_GAMES[result.id],metricValue=Number(result.metrics?.[profile.key]||0);
 state.rankGame=result.id;state.rankMode=state.newGameMode;
 showRunResult({
  won:result.win,
  title:result.win?'极限协议完成':'运行协议中断',
  value:`${formatScore(run.score)} PTS`,
  copy:`${profile.metric} ${metricValue.toLocaleString('zh-CN')} · 运行 ${fmt(result.time)}，分数已由原始玩法事件重新计算；${recordNotice(run)}。`,
  destination:'rank'
 });
}
const scoreInitSnake=initSnake,scoreInitBricks=initBricks,scoreInitTank=initTank,scoreInitArcade=initArcade;
initSnake=mode=>{markRunStart();scoreInitSnake(mode)};
initBricks=mode=>{markRunStart();scoreInitBricks(mode)};
initTank=mode=>{markRunStart();scoreInitTank(mode)};
initArcade=()=>{markRunStart();scoreInitArcade()};
function finishAdventure(result){
 if(state.runSettled)return;
 const run=persistRun(result.id,result.mode,result.time,result.win,result.metrics,result.endedReason||'run_ended');
 state.rankGame=result.id;state.rankMode=result.mode;
 const m=adventureMeta[result.id];
 showRunResult({won:result.win,title:result.win?(result.id==='platformer'?'群岛远征完成':'天亮了，街区守住了'):result.endedReason==='retired'?'本次挑战已收录':result.id==='platformer'?'下一跳，再出发':'街区防线失守',value:`${formatScore(run.score)} PTS`,copy:`${m.metric} ${result.metrics[m.key]} · 用时 ${fmt(result.time)}；${recordNotice(run)}。`,destination:'rank'});
}
function stopLoop(){clearInterval(state.drop);clearInterval(state.timer);stopWave();stopNewGameA();stopNewGameB();stopAdventure();state.playing=false}
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1)||'home';if(!routePages.includes(page))return;stopLoop();state.page=page;if(adventureIds.includes(page))state.adventureGame=page;render()});
function toast(msg){const t=document.querySelector('.toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
