app.addEventListener('click',e=>{const control=e.target.closest('[data-library-filter]');if(!control)return;const filter=control.dataset.libraryFilter;document.querySelectorAll('[data-library-filter]').forEach(button=>{const on=button===control;button.classList.toggle('active',on);button.setAttribute('aria-pressed',String(on))});document.querySelectorAll('.game-shelf .game-tile').forEach(tile=>{const button=tile.querySelector('button'),gameId=button?.dataset.openAdventure||button?.dataset.openWave||button?.dataset.openNewGame||button?.dataset.openNewB||button?.dataset.openArcade||(tile.classList.contains('blocks-tile')?'blocks':tile.classList.contains('snake-tile')?'snake':tile.classList.contains('brick-tile')?'bricks':'');const hasRecent=gameId&&listRuns({gameId,period:'week',limit:1}).length>0,hasRecord=gameId&&Boolean(getBestRun({gameId,period:'all'}));tile.hidden=filter==='recent'?!hasRecent:filter==='record'?!hasRecord:false})});
window.addEventListener('keydown',e=>{if(state.page!=='arcade-game')return;const dir={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down'}[e.key];if(dir){e.preventDefault();moveArcade(dir)}});
window.addEventListener('keydown',e=>{if(state.page==='game'){if(['ArrowLeft','ArrowRight','ArrowDown','ArrowUp'].includes(e.key))e.preventDefault();({ArrowLeft:'left',ArrowRight:'right',ArrowDown:'down',ArrowUp:'rotate'}[e.key])&&move({ArrowLeft:'left',ArrowRight:'right',ArrowDown:'down',ArrowUp:'rotate'}[e.key])}else if(state.page==='snake-game'){const dir={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down'}[e.key];if(dir){e.preventDefault();turnSnake(dir)}}else if(state.page==='brick-game'&&['ArrowLeft','ArrowRight','a','d'].includes(e.key)){e.preventDefault();brickMove(['ArrowLeft','a'].includes(e.key)?'left':'right')}else if(state.page==='tank-game'){const dir={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down'}[e.key];if(dir){e.preventDefault();moveTank(dir)}if(e.code==='Space'){e.preventDefault();fireTank()}}});window.addEventListener('keyup',e=>{if(state.page==='brick-game'&&['ArrowLeft','ArrowRight','a','d'].includes(e.key))state.brickHeld=0});render();
